grid=[[0]*22 for _ in range(22)]
def tile(r,c,border,center):
    for i in range(5):
        for j in range(5):
            grid[r+i][c+j]= center if 1<=i<=3 and 1<=j<=3 else border
placements=[(2,0,8,1),(8,0,8,3),(16,0,8,5),(14,5,8,6),(1,17,2,1),(4,12,2,4),(10,17,2,6),(15,17,2,7)]
for p in placements: tile(*p)
print('\n'.join(' '.join(map(str,row)) for row in grid))

